import{_ as t,c as a,o,a2 as i}from"./chunks/framework.CzULAunO.js";const n=JSON.parse('{"title":"Hello Ac-Wiki!","description":"","frontmatter":{"authors":["NekoMirra","ztm0929"],"date":{"created":"2024-10-18T00:00:00.000Z","updated":"2025-06-03T00:00:00.000Z"},"readtime":3,"tags":["Ac-Wiki"],"layout":"blog"},"headers":[],"relativePath":"docs/blog/posts/hello-ac-wiki.md","filePath":"docs/blog/posts/hello-ac-wiki.md","lastUpdated":1766652908000}'),l={name:"docs/blog/posts/hello-ac-wiki.md"};function r(p,e,c,s,_,d){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="hello-ac-wiki" tabindex="-1">Hello Ac-Wiki! <a class="header-anchor" href="#hello-ac-wiki" aria-label="Permalink to &quot;Hello Ac-Wiki!&quot;">​</a></h1><p>属于大学生群体的真·青年大学习。 本项目面向全体大学生群体设立，灵感来源于 <a href="https://t.me/High_School_Tutorial" target="_blank" rel="noreferrer">https://t.me/High_School_Tutorial</a> 在 Mirra 高中时期的学习中提供了诸多帮助，在此特别感谢！</p><p>项目的出发点在于锻炼自己的组织能力与检索信息能力，方便自己的同时也能惠及更多的学子</p><p>努力帮助大家学习掌握各项技能，最大程度的打破信息差，同时免去四处寻找各类书籍 / 材料 / 文档模板的困难</p><ol><li>声明</li></ol><p>1.1：本项目完全为自发组织的公益项目，我们随时欢迎您的参与和使用，并对您的付出与建议表达衷心的感谢</p><p>1.2：本项目英文名称 Ac-Wiki 中，Ac 为 Academy（学术）的简称，Wiki 意为百科，本项目与&quot;AcFun&quot;等并无主观或客观上的联系</p><p>1.3：本项目更新的信息 / 内容 / 文件等资料，可能来自于各类已有书籍 / 资料 / 文献，同时会积极的在互联网中引用，其他来源包括维护者们本人或群友们的经验分享，我们秉持尊重原则，尽可能注明引用来源，同时也提醒使用者对信息进行一定的辨别，本项目是参考建议性的而非说教性的，所有的内容仅供参考而非命令，您并不需要完全遵守这些内容，它也不一定完全适用于您，总之，请根据个人实际情况选用</p><p>1.4：基于本项目的性质，更新频率及生命周期并不能保证，我们特别呼吁愿意贡献 / 有过 Wiki 编辑经验 / 各行业专家用户参与到项目的维护与编写中，这样才可能使项目稳定的维持下去</p><p>1.5：频道关联群组 <a href="https://t.me/AcFourm" target="_blank" rel="noreferrer">https://t.me/AcFourm</a> 用作维护者与用户交流的场所，欢迎建言献策，友好沟通，群内交流并无过多约束，保持一个正常人应有的道德水平即可</p><p>1.6：本项目并不局限于此平台，为了维护方便，我们会积极考虑建立各式网站等，后期可能会迁移已有的更新内容</p><p>1.7：本项目欢迎您参与维护！可与我们联系参与维护或通过 PR 提交贡献，编写未完成的项目。</p>',12)]))}const k=t(l,[["render",r]]);export{n as __pageData,k as default};
